因为 GPT 要识别 api 的入参结构，所以我们需要给定一个 manifest 来描述这个 api （也就是 Function call 的 json schema）。我们做插件一期的时候，使用的是和 function call 一样的json schema 入参：
```json
{
  "api": [
      {
        "url": "http://localhost:3400/api/clothes",
        "name": "recommendClothes",
        "description": "根据用户的心情，给用户推荐他有的衣服",
        "parameters": {
          "properties": {
            "mood": {
              "description": "用户当前的心情，可选值有：开心（happy）, 难过（sad）,生气 （anger）,害怕（fear）,惊喜（ surprise）,厌恶 （disgust）",
              "enums": ["happy", "sad", "anger", "fear", "surprise", "disgust"],
              "type": "string"
            },
            "gender": {
              "type": "string",
              "enum": ["man", "woman"],
              "description": "对话用户的性别，需要询问用户后才知道这个信息"
            }
          },
          "required": ["mood", "gender"],
          "type": "object"
        }
      }
    ]
}
```
