## File 表

```ts
import {
  boolean,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  uuid,
  varchar,
} from 'drizzle-orm/pg-core';
import { createInsertSchema } from 'drizzle-zod';

import { idGenerator } from '../../utils/idGenerator';
import { createdAt, updatedAt } from './_helpers';
import { users } from './user';

export const asyncTasks = pgTable('async_tasks', {
  id: uuid('id').defaultRandom().primaryKey(),
  type: text('type'),
  status: text('status'),
  error: jsonb('error'),
  userId: text('user_id')
    .references(() => users.id, { onDelete: 'cascade' })
    .notNull(),
  duration: integer('duration'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export type NewAsyncTaskItem = typeof asyncTasks.$inferInsert;
export type AsyncTaskSelectItem = typeof asyncTasks.$inferSelect;

export const globalFiles = pgTable('global_files', {
  hashId: varchar('hash_id', { length: 64 }).primaryKey(),
  fileType: varchar('file_type', { length: 255 }).notNull(),
  size: integer('size').notNull(),
  url: text('url').notNull(),
  metadata: jsonb('metadata'),
  createdAt: createdAt(),
});

export type NewGlobalFile = typeof globalFiles.$inferInsert;
export type GlobalFileItem = typeof globalFiles.$inferSelect;

export const files = pgTable('files', {
  id: text('id')
    .$defaultFn(() => idGenerator('files'))
    .primaryKey(),

  userId: text('user_id')
    .references(() => users.id, { onDelete: 'cascade' })
    .notNull(),
  fileType: varchar('file_type', { length: 255 }).notNull(),
  fileHash: varchar('file_hash', { length: 64 }).references(() => globalFiles.hashId, {
    onDelete: 'no action',
  }),
  name: text('name').notNull(),
  size: integer('size').notNull(),
  url: text('url').notNull(),

  metadata: jsonb('metadata'),
  chunkTaskId: uuid('chunk_task_id').references(() => asyncTasks.id, { onDelete: 'set null' }),
  embeddingTaskId: uuid('embedding_task_id').references(() => asyncTasks.id, {
    onDelete: 'set null',
  }),

  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export type NewFile = typeof files.$inferInsert;
export type FileItem = typeof files.$inferSelect;

export const knowledgeBases = pgTable('knowledge_bases', {
  id: text('id')
    .$defaultFn(() => idGenerator('knowledgeBases'))
    .primaryKey(),

  name: text('name').notNull(),
  description: text('description'),
  avatar: text('avatar'),

  // different types of knowledge bases need to be distinguished
  type: text('type'),
  userId: text('user_id')
    .references(() => users.id, { onDelete: 'cascade' })
    .notNull(),

  isPublic: boolean('is_public').default(false),

  settings: jsonb('settings'),

  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const insertKnowledgeBasesSchema = createInsertSchema(knowledgeBases);

export type NewKnowledgeBase = typeof knowledgeBases.$inferInsert;
export type KnowledgeBaseItem = typeof knowledgeBases.$inferSelect;

export const knowledgeBaseFiles = pgTable(
  'knowledge_base_files',
  {
    knowledgeBaseId: text('knowledge_base_id')
      .references(() => knowledgeBases.id, { onDelete: 'cascade' })
      .notNull(),

    fileId: text('file_id')
      .references(() => files.id, { onDelete: 'cascade' })
      .notNull(),

    // userId: text('user_id')
    //   .references(() => users.id, { onDelete: 'cascade' })
    //   .notNull(),

    createdAt: createdAt(),
  },
  (t) => ({
    pk: primaryKey({
      columns: [
        t.knowledgeBaseId,
        t.fileId,
        // t.userId
      ],
    }),
  }),
);
```

1. `asyncTasks` 表

这个表用于跟踪异步任务的执行状态，对于管理文件处理和嵌入生成等长时间运行的任务非常重要。

- `id`: UUID，主键
- `type`: 任务类型
- `status`: 任务状态
- `error`: 存储任务执行过程中的错误信息
- `userId`: 关联到用户表，表示任务的所有者
- `duration`: 任务执行时间
- `createdAt` 和 `updatedAt`: 任务创建和更新时间

2. `globalFiles` 表

这个表存储全局唯一的文件信息，用于去重和共享文件。

- `hashId`: 文件的唯一哈希值，作为主键
- `fileType`: 文件类型
- `size`: 文件大小
- `url`: 文件的访问 URL
- `metadata`: 存储文件的额外元数据
- `createdAt`: 文件创建时间

3. `files` 表

这个表存储用户特定的文件信息，是 RAG 系统中文档管理的核心。

- `id`: 文件唯一标识符
- `userId`: 关联到用户表，表示文件的所有者
- `fileType`: 文件类型
- `fileHash`: 关联到 globalFiles 表，用于文件去重
- `name`: 文件名
- `size`: 文件大小
- `url`: 文件的访问 URL
- `metadata`: 存储文件的额外元数据
- `chunkTaskId` 和 `embeddingTaskId`: 关联到 asyncTasks 表，用于跟踪文件分块和嵌入生成任务
- `createdAt` 和 `updatedAt`: 文件创建和更新时间

4. `knowledgeBases` 表

这个表用于管理知识库，是组织和结构化文档集合的关键。

- `id`: 知识库唯一标识符
- `name`: 知识库名称
- `description`: 知识库描述
- `avatar`: 知识库头像
- `type`: 知识库类型
- `userId`: 关联到用户表，表示知识库的所有者
- `isPublic`: 表示知识库是否公开
- `settings`: 存储知识库的设置信息
- `createdAt` 和 `updatedAt`: 知识库创建和更新时间

5. `knowledgeBaseFiles` 表

这个表建立了知识库和文件之间的多对多关系。

- `knowledgeBaseId`: 关联到 knowledgeBases 表
- `fileId`: 关联到 files 表
- `createdAt`: 关联创建时间

这个表的主键是 `knowledgeBaseId` 和 `fileId` 的组合，确保了知识库和文件之间的唯一关联。

这些表共同构成了 RAG 系统的文档管理和知识库组织框架。`globalFiles` 和 `files` 表管理文件的存储和元数据，`knowledgeBases` 表组织知识结构，`knowledgeBaseFiles` 表将文件关联到特定的知识库。`asyncTasks` 表则支持了文件处理和嵌入生成等异步操作的管理。这种设计不仅支持高效的文档检索和知识管理，还为 RAG 系统提供了强大的可扩展性和灵活性，使系统能够处理大规模的文档集合并支持复杂的知识组织结构。

## 消息相关

```ts

// if the message contains a file
// save the file id and message id
export const messagesFiles = pgTable(
  'files_to_messages',
  {
    fileId: text('file_id')
      .notNull()
      .references(() => files.id, { onDelete: 'cascade' }),
    messageId: text('message_id')
      .notNull()
      .references(() => messages.id, { onDelete: 'cascade' }),
  },
  (t) => ({
    pk: primaryKey({ columns: [t.fileId, t.messageId] }),
  }),
);

export const messageRAG = pgTable('message_rag', {
  id: text('id')
    .references(() => messages.id, { onDelete: 'cascade' })
    .primaryKey(),
  query: text('query'),
  embeddingsId: uuid('embeddings_id').references(() => embeddings.id, { onDelete: 'set null' }),
});

export const messageFileChunks = pgTable(
  'message_file_chunks',
  {
    id: text('id').references(() => messages.id, { onDelete: 'cascade' }),
    queryId: text('query_id').references(() => messages.id, { onDelete: 'cascade' }),
    chunkId: uuid('chunk_id').references(() => chunks.id, { onDelete: 'cascade' }),
  },
  (t) => ({
    pk: primaryKey({ columns: [t.chunkId, t.id] }),
  }),
);

// convert message content to the chunks
// then we can use message as the RAG source
export const messageChunks = pgTable(
  'message_chunks',
  {
    messageId: text('message_id').references(() => messages.id, { onDelete: 'cascade' }),
    chunkId: uuid('chunk_id').references(() => chunks.id, { onDelete: 'cascade' }),
  },
  (t) => ({
    pk: primaryKey({ columns: [t.chunkId, t.messageId] }),
  }),
);

```

1. `messagesFiles` 表

这个表建立了消息和文件之间的多对多关系。

- `fileId`: 关联到 files 表，表示特定的文件
- `messageId`: 关联到 messages 表，表示特定的消息

主键是 `fileId` 和 `messageId` 的组合，确保了消息和文件之间的唯一关联。这个表允许系统跟踪哪些文件被包含在特定的消息中，对于理解消息上下文和相关资源非常重要。

2. `messageRAG` 表

这个表存储与消息相关的 RAG（检索增强生成）信息。

- `id`: 主键，关联到 messages 表
- `query`: 存储用于检索的查询文本
- `embeddingsId`: 关联到 embeddings 表，表示该消息的嵌入向量

这个表允许系统跟踪每条消息的 RAG 相关信息，包括用于检索的查询和对应的嵌入向量，这对于实现高效的相似性搜索和上下文检索至关重要。

3. `messageFileChunks` 表

这个表建立了消息、查询和文件分块之间的关系。

- `id`: 关联到 messages 表，表示特定的消息
- `queryId`: 关联到 messages 表，表示用于检索的查询消息
- `chunkId`: 关联到 chunks 表，表示检索到的文件分块

主键是 `chunkId` 和 `id` 的组合。这个表允许系统跟踪每条消息检索到的相关文件分块，对于理解消息的知识来源和上下文非常重要。

4. `messageChunks` 表

这个表将消息内容转换为分块，使消息本身也可以作为 RAG 的知识源。

- `messageId`: 关联到 messages 表，表示特定的消息
- `chunkId`: 关联到 chunks 表，表示消息内容的分块

主键是 `chunkId` 和 `messageId` 的组合。这个设计允许系统将消息内容分块存储，使得消息历史也可以作为知识源被检索和利用。

这些表共同构建了一个强大的消息处理和检索框架，是 RAG 系统的核心组成部分：

1. `messagesFiles` 表跟踪消息中包含的文件，为理解消息上下文提供了重要信息。
2. `messageRAG` 表存储每条消息的 RAG 相关信息，支持高效的相似性搜索。
3. `messageFileChunks` 表记录每条消息检索到的相关文件分块，有助于理解消息的知识来源。
4. `messageChunks` 表将消息内容转换为可检索的分块，使对话历史成为有价值的知识源。

这种设计不仅支持从外部文档和知识库中检索信息，还能利用对话历史作为动态知识源。这大大增强了系统的上下文理解能力和信息检索效率，使 RAG 系统能够提供更加智能和连贯的对话体验。

