### Next.js 服务端实现

```typescript
// src/utils/electron-ipc-client.ts
import net from 'net';
import fs from 'fs';
import os from 'os';
import path from 'path';

export class ElectronIPCClient {
  private socketPath: string | null = null;
  private connected: boolean = false;
  private socket: net.Socket | null = null;
  private requestQueue: Map<string, { resolve: Function, reject: Function }> = new Map();
  private reconnectTimeout: NodeJS.Timeout | null = null;
  private connectionAttempts: number = 0;
  private maxConnectionAttempts: number = 5;

  constructor() {
    this.initialize();
  }

  // 初始化客户端
  private initialize(): void {
    try {
      // 从临时文件读取套接字路径
      const tempDir = os.tmpdir();
      const socketInfoPath = path.join(tempDir, 'lobechat-electron-ipc-info.json');
      
      if (fs.existsSync(socketInfoPath)) {
        const socketInfo = JSON.parse(fs.readFileSync(socketInfoPath, 'utf-8'));
        this.socketPath = socketInfo.socketPath;
      } else {
        // 如果找不到套接字信息，使用默认路径
        this.socketPath = process.platform === 'win32'
          ? '\\\\.\\pipe\\lobechat-electron-ipc'
          : path.join(os.tmpdir(), 'lobechat-electron-ipc.sock');
      }
    } catch (err) {
      console.error('Failed to initialize IPC client:', err);
      this.socketPath = null;
    }
  }

  // 连接到 Electron IPC 服务器
  private connect(): Promise<void> {
    if (this.connected || !this.socketPath) {
      return Promise.resolve();
    }

    return new Promise((resolve, reject) => {
      try {
        this.socket = net.createConnection(this.socketPath, () => {
          this.connected = true;
          this.connectionAttempts = 0;
          console.log('Connected to Electron IPC server');
          resolve();
        });

        this.socket.on('data', (data) => {
          try {
            const response = JSON.parse(data.toString());
            const { id, result, error } = response;
            
            const pending = this.requestQueue.get(id);
            if (pending) {
              this.requestQueue.delete(id);
              if (error) {
                pending.reject(new Error(error));
              } else {
                pending.resolve(result);
              }
            }
          } catch (err) {
            console.error('Failed to parse response:', err);
          }
        });

        this.socket.on('error', (err) => {
          console.error('Socket error:', err);
          this.connected = false;
          this.handleDisconnect();
          reject(err);
        });

        this.socket.on('close', () => {
          console.log('Socket closed');
          this.connected = false;
          this.handleDisconnect();
        });
      } catch (err) {
        console.error('Failed to connect to IPC server:', err);
        this.handleDisconnect();
        reject(err);
      }
    });
  }

  // 处理断开连接
  private handleDisconnect(): void {
    // 清除重连定时器
    if (this.reconnectTimeout) {
      clearTimeout(this.reconnectTimeout);
      this.reconnectTimeout = null;
    }

    // 拒绝所有待处理的请求
    for (const [id, { reject }] of this.requestQueue) {
      reject(new Error('Connection to Electron IPC server lost'));
    }
    this.requestQueue.clear();

    // 尝试重新连接
    if (this.connectionAttempts < this.maxConnectionAttempts) {
      this.connectionAttempts++;
      const delay = Math.min(1000 * Math.pow(2, this.connectionAttempts - 1), 30000);
      
      this.reconnectTimeout = setTimeout(() => {
        this.connect().catch((err) => {
          console.error(`Reconnection attempt ${this.connectionAttempts} failed:`, err);
        });
      }, delay);
    }
  }

  // 发送请求到 Electron IPC 服务器
  public async sendRequest<T>(method: string, params: any = {}): Promise<T> {
    if (!this.socketPath) {
      throw new Error('Electron IPC connection not available');
    }

    // 如果未连接，先连接
    if (!this.connected) {
      await this.connect();
    }

    return new Promise<T>((resolve, reject) => {
      try {
        const id = Math.random().toString(36).substring(2, 15);
        const request = { id, method, params };
        
        // 将请求添加到队列
        this.requestQueue.set(id, { resolve, reject });
        
        // 设置超时
        const timeout = setTimeout(() => {
          this.requestQueue.delete(id);
          reject(new Error(`Request ${method} timed out`));
        }, 10000);
        
        // 发送请求
        this.socket!.write(JSON.stringify(request), (err) => {
          if (err) {
            clearTimeout(timeout);
            this.requestQueue.delete(id);
            reject(err);
          }
        });
      } catch (err) {
        reject(err);
      }
    });
  }

  // 获取数据库路径
  public async getDatabasePath(): Promise<string> {
    return this.sendRequest<string>('GET_DATABASE_PATH');
  }

  // 获取用户数据路径
  public async getUserDataPath(): Promise<string> {
    return this.sendRequest<string>('GET_USER_DATA_PATH');
  }

  // 关闭连接
  public close(): void {
    if (this.reconnectTimeout) {
      clearTimeout(this.reconnectTimeout);
      this.reconnectTimeout = null;
    }
    
    if (this.socket) {
      this.socket.end();
      this.socket = null;
    }
    
    this.connected = false;
  }
}

// 创建单例客户端
let ipcClientInstance: ElectronIPCClient | null = null;

export const getElectronIPCClient = (): ElectronIPCClient => {
  if (!ipcClientInstance) {
    ipcClientInstance = new ElectronIPCClient();
  }
  return ipcClientInstance;
};
```

在 Next.js 数据库模块中使用 IPC 客户端：

```typescript
// src/database/core/electron.ts
import { PGlite } from '@electric-sql/pglite';
import { drizzle as pgliteDrizzle } from 'drizzle-orm/pglite';
import * as schema from '@/database/schemas';
import { getElectronIPCClient } from '@/utils/electron-ipc-client';
import { LobeChatDatabase } from '../type';

// 初始化 PGLite 实例
export const getPgliteInstance = async (): Promise<LobeChatDatabase> => {
  try {
    // 从 Electron 主进程获取数据库路径
    const ipcClient = getElectronIPCClient();
    const dbPath = await ipcClient.getDatabasePath();
    
    // 初始化 PGLite
    const client = new PGlite(dbPath);
    
    return pgliteDrizzle({ client, schema }) as unknown as LobeChatDatabase;
  } catch (error) {
    console.error('Failed to initialize PGLite:', error);
    throw new Error(`Failed to initialize database: ${error.message}`);
  }
};
```

数据库工厂模式实现：

```typescript
// src/database/core/factory.ts
import { isDesktop } from '@/const/version';
import { getDBInstance as getWebDBInstance } from '@/database/core/web-server';
import { LobeChatDatabase } from '../type';

// 数据库实例缓存
let dbInstance: LobeChatDatabase | null = null;

// 根据环境创建适当的数据库实例
export const getDatabaseInstance = async (): Promise<LobeChatDatabase> => {
  // 如果已经有缓存的实例，直接返回
  if (dbInstance) return dbInstance;
  
  if (isDesktop) {
    // 动态导入 Electron 数据库模块
    const { getPgliteInstance } = await import('./electron');
    dbInstance = await getPgliteInstance();
    return dbInstance;
  } else {
    // Web 环境使用 Neon Postgres
    dbInstance = getWebDBInstance();
    return dbInstance;
  }
};
```

## 5. 错误处理和恢复机制

这个架构设计包含了以下错误处理和恢复机制：

1. **连接失败处理**：当无法连接到 IPC 服务器时，会进行指数退避重试
2. **请求超时处理**：所有请求都有超时机制，防止永久等待
3. **断线重连**：当连接断开时，会自动尝试重新连接
4. **请求队列管理**：维护请求队列，确保可以处理多个并发请求
5. **优雅降级**：在极端情况下，可以提供合理的默认值或错误提示

## 6. 部署考虑

### Electron 应用构建

在 `electron-builder.yml` 中，确保不会排除任何必要的模块：

```yaml
includeSubNodeModules: true

files:
  - build
  - from: '.next/standalone/demo/'
    to: '.next/standalone/demo/'
```

### Next.js 构建配置

在 `next.config.js` 中，确保 Electron 相关代码不会在 Web 构建中包含：

```javascript
module.exports = {
  output: 'standalone',
  webpack: (config, { isServer, dev }) => {
    // 排除 Electron 相关模块
    config.externals = [...(config.externals || []), 'electron'];
    
    return config;
  },
  experimental: {
    outputFileTracingIncludes: {
      '*': ['public/**/*', '.next/static/**/*'],
    },
  },
};
```

## 7. 总结

这个设计方案提供了一个完整的架构，使 Electron 主进程和 Next.js 服务端进程能够可靠地通信：

1. **分离关注点**：Electron 主进程负责系统资源访问，Next.js 服务端负责数据库管理和业务逻辑
2. **可靠通信**：使用命名管道/Unix 套接字实现高效、可靠的本地 IPC
3. **错误恢复**：包含完善的错误处理和恢复机制
4. **灵活扩展**：基于请求-响应协议，可以轻松扩展新的功能
5. **构建兼容**：通过动态导入和条件编译，确保 Web 和桌面版本可以共享大部分代码

这种架构允许你在不同环境中使用相同的代码库，同时充分利用 Electron 的系统能力和 Next.js 的 Web 功能。

## IPC 进程间通信

### electron-client-ipc （Render 进程与 Main 进程通信）

设计一个框架来实现轻巧的 Render 端与 main 端通信

1. 定义 render 的触发 events:

```ts
export interface DevtoolsDispatchEvents {
  /**
   * open the LobeHub Devtools
   */
  openDevtools: () => void;
}

```

2. 定义 render层（next client 端）的service:

```ts
import { dispatch } from '@/utils/electron/dispatch';

class DevtoolsService {
  async openDevtools(): Promise<void> {
    return dispatch('openDevtools');
  }
}

export const electronDevtoolsService = new DevtoolsService();
```

3. dispatch 中实现关键的调用逻辑，并做到类型友好：

```ts
// src/utils/electron/dispatch.ts
import { DispatchInvoke } from '@lobechat/electron-client-ipc';

/**
 * client 端请求 sketch 端 event 数据的方法
 */
export const dispatch: DispatchInvoke = async (event, ...data) => {
  if (!window.electronAPI) throw new Error('electronAPI not found');

  return window.electronAPI?.invoke(event, ...data);
};
```



这样应用层使用就可以当成是一个普通的 Service 来使用：
```ts
 onClick={async () => {
  if (isDesktop) {
    const { electronDevtoolsService } = await import('@/services/electron/devtools');

    await electronDevtoolsService.openDevtools();

    return;
  }
```

## Main 端配置存储机制

### 概述

大部分用户侧的业务数据将通过 pglite 存储，因此在 main 端使用基于 electron-store 的，轻量化实现一些设置数据的持久化，用于管理应用配置。本文档描述了当前的实现和方法。

#### 存储管理类 `StoreManager`

`StoreManager` 类封装了对 electron-store 的操作，提供以下核心功能：

- **构造函数**：接收 App 实例，初始化存储
- **数据操作**：提供了增删改查等完整操作
- **高级功能**：支持在编辑器中打开配置文件

#### 核心方法

| 方法 | 说明 | 参数 | 返回值 |
|------|------|------|--------|
| `get` | 获取配置项 | `key`: 配置键<br>`defaultValue?`: 默认值 | 配置值 |
| `set` | 设置配置项 | `key`: 配置键<br>`value`: 配置值 | 无 |
| `delete` | 删除配置项 | `key`: 配置键 | 无 |
| `clear` | 清空所有配置 | 无 | 无 |
| `has` | 检查配置项是否存在 | `key`: 配置键 | `boolean` |
| `openInEditor` | 在编辑器中打开配置文件 | 无 | `Promise<void>` |

#### 使用示例

```typescript
// 初始化
const store = new StoreManager(app);

// 获取配置
const value = store.get('someKey');

// 设置配置
store.set('someKey', newValue);

// 检查配置是否存在
if (store.has('optionalFeature')) {
  // 执行相关操作
}

// 删除配置
store.delete('temporaryConfig');

// 在开发环境中直接编辑配置文件
await store.openInEditor();
```

