```typescript
// src/integrations/datadog/index.ts
import { ILogger } from '../../core/types';

// Datadog配置
export interface DatadogConfig {
  enabled?: boolean;
  clientToken?: string;
  site?: string;
  service?: string;
  env?: string;
  version?: string;
  sampleRate?: number;
}

// 包装器工厂函数 - 为任何日志器添加Datadog功能
export function withDatadog(baseLogger: ILogger, config: DatadogConfig): ILogger {
  // 如果没有启用或缺少配置，返回原始日志器
  if (!config.enabled || !config.clientToken) {
    return baseLogger;
  }
  
  // 根据环境选择适当的Datadog集成
  const isClient = typeof window !== 'undefined';
  let datadogImpl: any;
  
  // 初始化Datadog集成
  if (isClient) {
    // 客户端实现（浏览器）
    initBrowserDatadog(config);
    datadogImpl = getDatadogBrowserInstance();
  } else {
    // 服务器端实现
    initNodeDatadog(config);
    datadogImpl = getDatadogNodeInstance();
  }
  
  // 创建代理日志器，保持原始API但添加Datadog集成
  const datadogLogger: ILogger = {
    ...baseLogger,
    
    // 重写日志方法，发送到Datadog
    trace: (...args) => {
      baseLogger.trace(...args);
      sendToDatadog('debug', args, datadogImpl);
    },
    debug: (...args) => {
      baseLogger.debug(...args);
      sendToDatadog('debug', args, datadogImpl);
    },
    info: (...args) => {
      baseLogger.info(...args);
      sendToDatadog('info', args, datadogImpl);
    },
    warn: (...args) => {
      baseLogger.warn(...args);
      sendToDatadog('warn', args, datadogImpl);
    },
    error: (...args) => {
      baseLogger.error(...args);
      sendToDatadog('error', args, datadogImpl);
    },
    fatal: (...args) => {
      baseLogger.fatal(...args);
      sendToDatadog('error', args, datadogImpl);
    },
    
    // 扩展方法
    success: (...args) => {
      baseLogger.success(...args);
      sendToDatadog('info', args, datadogImpl);
    },
    ready: (...args) => {
      baseLogger.ready(...args);
      sendToDatadog('info', args, datadogImpl);
    },
    start: (...args) => {
      baseLogger.start(...args);
      sendToDatadog('info', args, datadogImpl);
    },
    
    // 创建带标签的子日志器
    withTag: (tag) => {
      return withDatadog(baseLogger.withTag(tag), config);
    },
    
    // Datadog特有的指标方法
    metric: (name, value, tags) => {
      if (datadogImpl && datadogImpl.metric) {
        datadogImpl.metric(name, value, tags);
      }
    }
  };
  
  return datadogLogger;
}

