### 6. 主入口和注册 (index.ts)

```typescript
// src/index.ts
import { LogLevel, LoggerConfig, ILogger } from './core/types';
import { container } from './core/container';
import { createLogger, logger } from './factory';
import { ConsolaAdapter } from './adapters/consola';
import { ElectronLogAdapter } from './adapters/electron';
import { withDatadog } from './integrations/datadog';

// 注册默认适配器
container.registerAdapter('consola', new ConsolaAdapter());
container.registerAdapter('electron-log', new ElectronLogAdapter());

// 初始化日志系统
export function initializeLogger(config: LoggerConfig): void {
  container.setConfig(config);
}

// 返回带有集成的日志器
export function createLoggerWithIntegrations(config: LoggerConfig = {}): ILogger {
  let loggerInstance = createLogger(config);
  
  // 添加Datadog集成
  if (config.datadog?.enabled) {
    loggerInstance = withDatadog(loggerInstance, config.datadog);
  }
  
  // 这里可以添加更多集成...
  
  return loggerInstance;
}

// 导出
export {
  logger,           // 默认日志器
  createLogger,     // 创建基础日志器
  LogLevel,         // 日志级别枚举
  withDatadog,      // Datadog集成
};

// 类型导出
export type {
  ILogger,          // 日志器接口
  LoggerConfig,     // 配置接口
};
